-- GENERATED by `python -m hearth generate` from metadata/sources/zillow_zhvi_zip.yml. Do not edit.
-- Zillow Home Value Index (ZHVI) by ZIP code: one row per zip and month.
-- Uses the most recent load only; the wide file is unpivoted from its rescued-data JSON.
with src as (
    select * from {{ source('bronze', 'zillow_zhvi_zip') }}
),

latest_load as (
    select * from src
    where _loaded_at = (select max(_loaded_at) from src)
),

unpivoted as (
    select
        l.*,
        p.key as _period,
        p.value as _value
    from latest_load as l
    lateral view explode(from_json(l._rescued_data, 'map<string,string>')) p as key, value
    where p.key rlike '^\\d{4}-\\d{2}-\\d{2}$'
),

renamed as (
    select
        cast(nullif(trim(RegionName), '') as string) as zip,
        cast(nullif(trim(State), '') as string) as state,
        cast(nullif(trim(CountyName), '') as string) as county_name,
        cast(nullif(trim(Metro), '') as string) as metro_name,
        cast(nullif(trim(_period), '') as date) as month_end,
        cast(nullif(trim(_value), '') as decimal(14,2)) as zhvi,
        _source_file,
        _loaded_at
    from unpivoted
)

select * from renamed
